import calendar
from datetime import date, timedelta


def recur(start: str, rule: str, count: int) -> list[str]:
    weekdays = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}
    start_date = date.fromisoformat(start)
    parts = rule.split()
    freq = parts[0]
    k = int(parts[1])
    res: list[str] = []

    if freq == "DAILY":
        return [(start_date + timedelta(days=i * k)).isoformat() for i in range(count)]

    if freq == "WEEKLY":
        target_days = sorted(weekdays[d] for d in parts[2].split(","))
        week0_monday = start_date - timedelta(days=start_date.weekday())
        w = 0
        while len(res) < count:
            week_monday = week0_monday + timedelta(days=w * 7)
            for wd in target_days:
                cand = week_monday + timedelta(days=wd)
                if cand >= start_date:
                    res.append(cand.isoformat())
                    if len(res) == count:
                        break
            w += k
        return res

    if freq == "MONTHLY":
        m_offset = 0
        base_months = start_date.year * 12 + (start_date.month - 1)
        if len(parts) == 3:
            d = int(parts[2])
            while len(res) < count:
                year, month0 = divmod(base_months + m_offset, 12)
                month = month0 + 1
                days_in_month = calendar.monthrange(year, month)[1]
                day = days_in_month if d == -1 else d
                if day <= days_in_month:
                    cand = date(year, month, day)
                    if cand >= start_date:
                        res.append(cand.isoformat())
                m_offset += k
        else:
            n = int(parts[2])
            target_wd = weekdays[parts[3]]
            while len(res) < count:
                year, month0 = divmod(base_months + m_offset, 12)
                month = month0 + 1
                first_wd, days_in_month = calendar.monthrange(year, month)
                if n == -1:
                    day = days_in_month - ((first_wd + days_in_month - 1 - target_wd) % 7)
                else:
                    first_occ = 1 + ((target_wd - first_wd) % 7)
                    day = first_occ + (n - 1) * 7
                if day <= days_in_month:
                    cand = date(year, month, day)
                    if cand >= start_date:
                        res.append(cand.isoformat())
                m_offset += k
        return res

    if freq == "YEARLY":
        mm, dd = map(int, parts[2].split("-"))
        year = start_date.year
        while len(res) < count:
            if dd <= calendar.monthrange(year, mm)[1]:
                cand = date(year, mm, dd)
                if cand >= start_date:
                    res.append(cand.isoformat())
            year += k
        return res

    raise ValueError(f"Unsupported rule: {rule}")
